import * as THREE from '../../vendor/three.module.js';
const materials=new Map();
// Fixed, shared LED canvases: the performance budget does not depend on the
// number of billboard meshes. Only the stage changes, never a per-frame texture.
export function screenMaterial(mode){if(materials.has(mode))return materials.get(mode);const c=document.createElement('canvas');c.width=1536;c.height=768;const x=c.getContext('2d'),text=(s,px,py,size,col='#fff4cd')=>{x.fillStyle=col;x.font=`900 ${size}px "Microsoft YaHei",sans-serif`;x.save();x.translate(px,py);x.scale(.65,1);x.fillText(s,0,0);x.restore();};x.fillStyle=mode==='hijack'?'#260e29':mode==='dolphin'?'#071e2b':'#102c39';x.fillRect(0,0,c.width,c.height);x.textAlign='center';x.fillStyle='#4bddcd';x.fillRect(0,0,1536,14);x.fillRect(0,754,1536,14);
 if(mode==='dolphin'){x.fillStyle='#54e6d8';x.beginPath();x.moveTo(112,385);x.bezierCurveTo(180,211,340,185,484,297);x.bezierCurveTo(537,329,573,353,622,357);x.lineTo(580,385);x.bezierCurveTo(528,390,463,374,428,358);x.bezierCurveTo(350,394,345,430,353,482);x.lineTo(288,438);x.bezierCurveTo(214,439,165,415,129,405);x.lineTo(83,462);x.lineTo(93,387);x.lineTo(39,339);x.lineTo(112,385);x.fill();x.beginPath();x.moveTo(266,262);x.lineTo(305,170);x.lineTo(340,262);x.fill();x.fillStyle='#0c2838';x.beginPath();x.arc(442,303,9,0,Math.PI*2);x.fill();text('豚师',1057,365,222);text('海 豚 帮 · 今 晚 不 打 烊',1047,458,43,'#75eddf');text('放学以后，把账算明白。',768,607,67);text('五一的灯，别只替一个人亮。',768,698,32,'#a9d6d7');}
 else if(mode==='public'){text('豚师 · 五一的钱去了哪里？',768,107,66);const n=[['酒吧 / 游乐 / 牌馆',242,269],['河东联投',768,269],['同一批人开的公司',1294,269],['店主交过的钱',242,520],['牢东杰关联公司',768,520],['人和钱搬去了湘江',1294,520]];x.strokeStyle='#4edbc8';x.lineWidth=9;for(const [a,b]of[[0,1],[1,2],[3,1],[1,4],[2,4],[4,5]]){x.beginPath();x.moveTo(n[a][1],n[a][2]);x.lineTo(n[b][1],n[b][2]);x.stroke();}for(const [s,px,py]of n){x.fillStyle='#173f50';x.fillRect(px-211,py-66,422,132);text(s,px,py+13,37);}text('店主签过字 · 钱付给了谁 · 哪天收走的',768,689,42);}
 else if(mode==='hijack'){x.strokeStyle='#e870bd';x.lineWidth=10;for(let y=180;y<650;y+=68){x.beginPath();x.moveTo(0,y);x.lineTo(1536,y+30);x.stroke();}x.fillStyle='#260e29';x.fillRect(120,207,1296,340);text('牢东杰',768,146,74,'#f8b8df');text('两块钱的公司，',768,350,104);text('也敢来算我的账？',768,489,91);text('五一只是账面。',768,689,53,'#e8a5d0');}
 else {text('长沙 · 放学以后',768,169,84);text('黄兴路的夜，才刚开始。',768,418,94,'#72e3d4');text('南门口 / 黄兴广场 / 五一',768,665,47);}
 const map=new THREE.CanvasTexture(c);map.colorSpace=THREE.SRGBColorSpace;const m=new THREE.MeshStandardMaterial({map,emissiveMap:map,emissive:'#ffffff',emissiveIntensity:mode==='dolphin'?1.15:.85,roughness:.7});m.name='c4-led-'+mode;m.userData.screenContent=mode;materials.set(mode,m);return m;
}
export function addStoryScreen(k,{x,y,z,w,h,angle=0,main=false}){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),screenMaterial('ads'));m.position.set(x,y,z);m.rotation.y=angle;m.name='c4-live-screen';Object.assign(m.userData,{cityScreen:true,mainScreen:main,mounted:true});k.root.add(m);return m;}
